import type { HostConfig } from '@/lib/ssh'

/**
 * A real `configreport` response, for the design harness.
 *
 * GENERATED BY RUNNING THE ACTUAL VERB, not written by hand, and that is the
 * whole reason it can be trusted. `synth.ts` next door records what a
 * hand-written fixture costs: it spelled player states in uppercase, the game
 * sends lowercase, and every state filter worked in the harness and none of
 * them worked in production (#17). A harness that exercises a shape the wire
 * cannot produce is worse than no harness, because it is believed.
 *
 * So this is `tools/dispatch.sh`'s `configreport` output from the game repo,
 * run against a copy of the deployed layout, with only the absolute paths and
 * the three timestamps rewritten to what a real box would report. Every
 * convar, every group, every value string is verbatim.
 *
 * REGENERATE IT RATHER THAN EDIT IT whenever the allowlist changes, from a
 * checkout of the game repo:
 *
 *   SSH_ORIGINAL_COMMAND=configreport BR_SERVER_ROOT=<server root> \
 *     bash tools/dispatch.sh
 *
 * NOTE WHAT THE CONVARS LOOK LIKE HERE. Every `voice_*` comes back
 * `source: 'default'` with a null value, because there are no voice lines in
 * server.cfg and there are not meant to be. That is precisely the answer #150
 * spent a round failing to get, and it is the clearest illustration of why the
 * source matters as much as the value. If a future regeneration shows them
 * set, check that is really true of the box rather than convenient for a
 * screenshot.
 */
